// Playback of pre-recorded sentences. Files live in public/voices/<character>/<id>.<extension>,
// the list of what exists is in public/voices/index.json (generated by `npm run voices:index`
// on every build). Recordings made on the recording page and stored in the browser take precedence.
// Whatever is not recorded is still said by speech synthesis.
import { splitSentence, type Segment } from './keys';
import { recordingKey, recordingKeys, loadRecording } from './storage';

/** character → segment id → file extension */
export type VoiceIndex = Record<string, Record<string, string>>;

const BASE = `${import.meta.env?.BASE_URL ?? './'}voices/`;
/** the longest to wait for a recording to download before the sentence is said by synthesis */
const MAX_LOAD_TIME = 3000;

let index: Promise<VoiceIndex> | null = null;
let local: Promise<Set<string>> | null = null;

export function loadIndex(): Promise<VoiceIndex> {
  return (index ??= fetch(`${BASE}index.json`, { cache: 'no-cache' })
    .then((r) => (r.ok ? r.json() : {}))
    .catch(() => ({})));
}

/** After recording a new sentence on the recording page, so that the game knows it right away. */
export function refreshLocal() {
  local = recordingKeys();
  buffers.clear();
}

/** Does the character have any recordings at all? */
export async function hasRecordings(characterId?: string): Promise<boolean> {
  const [idx, m] = await Promise.all([loadIndex(), (local ??= recordingKeys())]);
  if (characterId) return Object.keys(idx[characterId] ?? {}).length > 0 || [...m].some((k) => k.startsWith(`${characterId}/`));
  return Object.values(idx).some((p) => Object.keys(p).length > 0) || m.size > 0;
}

let context: AudioContext | null = null;

function getContext(): AudioContext | null {
  if (context) return context;
  const AC = typeof window !== 'undefined' ? window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext : undefined;
  if (!AC) return null;
  context = new AC();
  return context;
}

/** Browsers only play sound after a click. Called synchronously from a click handler. */
export function unlock() {
  const k = getContext();
  if (k && k.state === 'suspended') k.resume().catch(() => {});
}

if (typeof window !== 'undefined') {
  for (const event of ['pointerdown', 'keydown', 'touchend']) window.addEventListener(event, unlock, { capture: true });
}

/** A recording segment without silence at the start and end, with normalized loudness. */
export interface Clip {
  buffer: AudioBuffer;
  start: number;
  end: number;
  gain: number;
}

/** Finds where the recording is speaking and how much to amplify it so that all sentences are equally loud. */
export function trim(buffer: AudioBuffer): Clip {
  const data = buffer.getChannelData(0);
  const frame = Math.max(1, Math.round(buffer.sampleRate * 0.01));
  const energy: number[] = [];
  let peak = 0;
  for (let i = 0; i < data.length; i += frame) {
    let s = 0;
    const finish = Math.min(data.length, i + frame);
    for (let j = i; j < finish; j++) {
      s += data[j] * data[j];
      peak = Math.max(peak, Math.abs(data[j]));
    }
    energy.push(Math.sqrt(s / (finish - i)));
  }
  const maxEnergy = Math.max(...energy, 1e-6);
  const threshold = Math.max(maxEnergy * 0.08, 0.004);
  const first = energy.findIndex((e) => e > threshold);
  let last = energy.length - 1;
  while (last > 0 && energy[last] <= threshold) last--;
  if (first < 0) return { buffer, start: 0, end: buffer.duration, gain: 1 };
  const start = Math.max(0, (first * frame) / buffer.sampleRate - 0.06);
  const endTime = Math.min(buffer.duration, ((last + 1) * frame) / buffer.sampleRate + 0.12);
  return { buffer, start, end: endTime, gain: Math.min(0.9 / Math.max(peak, 1e-4), 6) };
}

async function decode(data: ArrayBuffer): Promise<Clip | null> {
  const k = getContext();
  if (!k) return null;
  try {
    return trim(await k.decodeAudioData(data));
  } catch {
    return null;
  }
}

/** Loads and prepares a recording from a Blob (recording page). */
export async function clipFromBlob(blob: Blob): Promise<Clip | null> {
  return decode(await blob.arrayBuffer());
}

const buffers = new Map<string, Promise<Clip | null>>();

function loadSegment(characterId: string, u: Segment, idx: VoiceIndex, m: Set<string>): Promise<Clip | null> | null {
  const key = recordingKey(characterId, u.id);
  const extension = idx[characterId]?.[u.id];
  if (!m.has(key) && !extension) return null;
  let p = buffers.get(key);
  if (!p) {
    p = (async () => {
      const n = m.has(key) ? await loadRecording(key).catch(() => undefined) : undefined;
      if (n) return decode(await n.blob.arrayBuffer());
      if (!extension) return null;
      const r = await fetch(`${BASE}${characterId}/${u.id}.${extension}`);
      return r.ok ? decode(await r.arrayBuffer()) : null;
    })().catch(() => null);
    buffers.set(key, p);
    // a failed download is retried next time
    p.then((z) => z === null && buffers.delete(key));
  }
  return p;
}

/**
 * Prepares the recordings for one sentence. Returns null when some segment of the sentence
 * is not recorded or does not load in time; then synthesis says it.
 */
export async function prepareSentence(characterId: string, sentence: string): Promise<Clip[] | null> {
  if (!getContext()) return null;
  const [idx, m] = await Promise.all([loadIndex(), (local ??= recordingKeys())]);
  const loading = splitSentence(characterId, sentence).map((u) => loadSegment(characterId, u, idx, m));
  if (loading.some((n) => n === null)) return null;
  const limit = new Promise<null>((r) => setTimeout(() => r(null), MAX_LOAD_TIME));
  const clips = await Promise.race([Promise.all(loading), limit]);
  if (!clips || clips.some((z) => z === null)) return null;
  return clips as Clip[];
}

let playing: AudioBufferSourceNode[] = [];

export function stop() {
  for (const s of playing) {
    try {
      s.stop();
    } catch {
      // already finished playing
    }
  }
  playing = [];
}

/** Plays the segments back to back (sentence start, animal name, ending) and waits until they fade out. */
export function playClips(clips: Clip[]): Promise<void> {
  const k = getContext();
  if (!k || clips.length === 0) return Promise.resolve();
  stop();
  let time = k.currentTime + 0.03;
  const sources = clips.map((z) => {
    const source = k.createBufferSource();
    source.buffer = z.buffer;
    const gainNode = k.createGain();
    gainNode.gain.value = z.gain;
    source.connect(gainNode).connect(k.destination);
    source.start(time, z.start, z.end - z.start);
    time += z.end - z.start;
    return source;
  });
  playing = sources;
  const length = time - k.currentTime;
  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      clearTimeout(safetyTimer);
      resolve();
    };
    // a suspended context (e.g. iOS without a click) would otherwise wait forever
    const safetyTimer = setTimeout(finish, length * 1000 + 1500);
    sources[sources.length - 1].onended = finish;
  });
}
